 private static void Invoke(Button button)=>((IInvokeProvider)UIElementAutomationPeer.CreatePeerForElement(button)!.GetPattern(PatternInterface.Invoke)).Invoke();
 public static async Task Run(PageWindow w,string directory)
 {
  Directory.CreateDirectory(directory);var started=DateTimeOffset.Now;var checks=new List<object>();var success=true;var cursor=NativeInput.CursorPosition;
  void Verify(string name,bool pass,object? detail=null){checks.Add(new{name,passed=pass,detail});if(!pass)throw new InvalidOperationException(name);}
  void Shot(string name,Window? window=null)=>NativeCapture.Save((FrameworkElement)(window??w).Content,Path.Combine(directory,name+".png"));
  async Task<PlanForm> Open(ReminderPlan? plan=null,bool medication=false){var form=w.OpenEditor(plan,medication);await Task.Delay(220);return form;}
  void Close(PlanForm f){f.VerificationClose=true;f.Close();}
  try{
   await Task.Delay(300);Verify("不依赖数据库与旧桌面程序",!typeof(PageWindow).Assembly.GetReferencedAssemblies().Any(x=>x.Name is "Pausewell.Storage" or "Pausewell.Desktop"));Verify("首页展示三条普通事项",w.PlanToggles.Count==3&&w.Session.Engine.State.Plans.Count==4);Shot("01-home");
   var original=w.Session.Engine.State.Plans.First(x=>x.Kind==HabitKind.Water);var f=await Open(original);Shot("02-ordinary-editor",f);Verify("已有值进入普通表单",f.NameInput.Text=="喝水"&&f.IntervalInput.Text=="30");f.NameInput.Text="";f.IntervalInput.Text="0";Verify("普通字段级错误阻止保存",!f.TrySave()&&FieldState.GetHasError(f.NameInput)&&FieldState.GetHasError(f.IntervalInput)&&f.IsVisible);await Task.Delay(100);Shot("03-ordinary-errors",f);
   f.NameInput.Text="喝水（已修改）";f.IntervalInput.Text="35";f.KindInput.SelectedIndex=1;Verify("活动条件字段显示且自定义名称保留",f.DurationSection.IsVisible&&f.NameInput.Text=="喝水（已修改）");f.DurationInput.Text="3601";Verify("活动时长上界校验",!f.TrySave()&&FieldState.GetHasError(f.DurationInput));f.DurationInput.Text="120";f.KindInput.SelectedIndex=0;f.More.IsExpanded=true;f.ScheduleInput.SelectedIndex=1;await Task.Delay(60);Verify("切换固定时刻隐藏间隔",!f.IntervalSection.IsVisible&&f.TimeSection.IsVisible);f.TimeFields.Inputs[0].Text="10:00";f.ScheduleInput.SelectedIndex=0;Verify("切回间隔保留输入",f.IntervalInput.Text=="35"&&f.TimeFields.Inputs[0].Text=="10:00");
   f.UseWindow.IsChecked=true;f.UseWindow.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));f.WindowStart.Text="18:00";f.WindowEnd.Text="09:00";Verify("有效时段倒置被阻止",!f.TrySave()&&FieldState.GetHasError(f.WindowEnd));f.WindowStart.Text="09:00";f.WindowEnd.Text="18:00";Shot("04-ordinary-expanded",f);w.Session.Store.FailNextSave=true;var saves=w.Session.Store.SaveCount;Verify("模拟保存失败保留表单与状态",!f.TrySave()&&f.IsVisible&&f.NameInput.Text=="喝水（已修改）"&&w.Session.Store.SaveCount==saves&&w.Session.Engine.State.Plans.Single(x=>x.Id==original.Id).Name=="喝水");Shot("05-save-failure",f);Verify("重试保存更新真实核心状态",f.TrySave()&&w.Session.Engine.State.Plans.Single(x=>x.Id==original.Id).IntervalMinutes==35);var savedCount=w.Session.Store.SaveCount;Verify("已提交表单阻止重复保存",!f.TrySave()&&w.Session.Store.SaveCount==savedCount);await Task.Delay(120);Verify("保存返回列表显示成功反馈",w.CurrentEditor==null&&w.IsEnabled&&w.Feedback.Text.Contains("已保存"));Shot("06-home-saved");
   var count=w.Session.Engine.State.Plans.Count;f=await Open();f.NameInput.Text="不应保存";Verify("表单可接收自身键盘输入",NativeInput.Activate(f));f.StyleInput.Focus();f.StyleInput.IsDropDownOpen=true;await Task.Delay(100);NativeInput.Key(0x1B);await Task.Delay(100);Verify("Esc 优先关闭下拉而不退出表单",f.IsVisible&&!f.StyleInput.IsDropDownOpen&&!f.DiscardNotice.IsVisible);f.RequestCancel();Verify("有修改取消显示放弃选项",f.DiscardNotice.IsVisible&&f.IsVisible);Shot("07-unsaved-cancel",f);Invoke(f.DiscardButton);await Task.Delay(80);Verify("放弃不增加计划",w.Session.Engine.State.Plans.Count==count&&w.CurrentEditor==null);
   w.SelectPage(1);await Task.Delay(80);Shot("08-medicine-list");f=await Open(w.Session.Engine.State.Plans.Single(x=>x.Kind==HabitKind.Medication),true);Shot("09-medicine-editor",f);Verify("药物不显示普通工作日字段",!f.Workdays.IsVisible&&!f.IntervalSection.IsVisible&&f.TimeFields.Count==2);f.TimeFields.SetCount(3);f.TimeFields.Inputs[2].Text="13:00";f.TimeFields.SetCount(1);f.TimeFields.SetCount(3);Verify("减少再增加恢复时刻草稿",f.TimeFields.Inputs[2].Text=="13:00"&&f.TimeFields.Inputs[0].Text=="08:00");f.TimeFields.Inputs[1].Text="08:00";Verify("重复服药时刻字段级校验",!f.TrySave()&&FieldState.GetHasError(f.TimeFields.Inputs[1]));await Task.Delay(100);Shot("10-medicine-errors",f);f.TimeFields.Inputs[1].Text="20:00";f.HasEnd.IsChecked=true;f.HasEnd.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));f.Ends.SetRawInput("2026-10-15");var rangeSaved=f.TrySave();Verify("日期倒置保留并报错",!rangeSaved&&FieldState.GetHasError(f.Ends)&&f.Ends.SelectedDate==new DateTime(2026,10,15),new{saved=rangeSaved,error=FieldState.GetError(f.Ends),start=f.Starts.SelectedDate,end=f.Ends.SelectedDate,hasEnd=f.HasEnd.IsChecked,summary=f.SummaryError.Text});f.Ends.SetRawInput("2026-10-17");f.EnabledInput.IsChecked=true;f.UpdatePreview();Verify("药物预览按固定时刻计算",f.Preview.Text.Contains("10-16 13:00")&&f.Preview.Text.Contains("10-16 20:00"));Shot("11-medicine-three-times",f);Verify("药物保存按时刻列表且不继承工作日",f.TrySave()&&w.Session.Engine.State.Plans.Single(x=>x.Kind==HabitKind.Medication).Times.Count==3&&!w.Session.Engine.State.Plans.Single(x=>x.Kind==HabitKind.Medication).WorkdaysOnly);await Task.Delay(100);Shot("12-medicine-saved");
   w.SelectPage(0);Invoke(w.PauseButton);await Task.Delay(80);Verify("首页暂停状态明确",w.PageTitle.Text.Contains("暂停")&&w.Session.Engine.State.PauseUntil!=null);Shot("13-paused");f=await Open();f.UpdatePreview();Verify("暂停中新增预览保持暂停",f.Preview.Text.Contains("保持暂停"));Close(f);await Task.Delay(100);Invoke(w.PauseButton);await Task.Delay(100);Invoke(w.MeetingButton);await Task.Delay(100);Verify("会议状态反映真实核心模式",w.PageTitle.Text=="会议中"&&w.Session.Engine.State.MeetingUntil!=null);Shot("14-meeting");Invoke(w.MeetingButton);await Task.Delay(100);
   foreach(var plan in w.Session.Engine.State.Plans.Where(x=>x.Kind!=HabitKind.Medication).ToArray())w.Session.Engine.SetEnabled(plan.Id,false,w.Session.Now);w.Refresh();Verify("全部停用标题不再显示提醒中",w.PageTitle.Text=="暂无运行中的提醒");Shot("15-all-disabled");foreach(var plan in w.Session.Engine.State.Plans.Where(x=>x.Kind!=HabitKind.Medication).ToArray())w.Session.Engine.SetEnabled(plan.Id,true,w.Session.Now);w.Refresh();
   f=await Open(null,true);Verify("新增药物不预填服药时间",f.TimeFields.Inputs.All(x=>x.Text==""));f.NameInput.Text="一个非常长的药物名称用于验证完整字段排版和列表省略提示，不代指真实药物或实际用药建议";f.TimeFields.SetCount(6);for(var i=0;i<6;i++)f.TimeFields.Inputs[i].Text=$"{i+10:00}:00";f.NoteInput.Text=string.Join("\n",Enumerable.Repeat("按已有要求填写的示例说明。",10));await Task.Delay(80);Shot("16-medicine-six-times",f);Verify("超过四次可编辑并保留六个时刻",f.TimeFields.Count==6&&f.TimeFields.Validate(false));f.Height=600;await Task.Delay(100);Shot("17-compact-medicine",f);var bottom=f.SaveButton.TranslatePoint(new Point(0,f.SaveButton.ActualHeight),(FrameworkElement)f.Content).Y;Verify("紧凑表单保存仍在客户区内",bottom<=((FrameworkElement)f.Content).ActualHeight&&f.BodyScroll.ScrollableHeight>0);Verify("六时刻计划可保存并返回列表",f.TrySave());w.SelectPage(1);await Task.Delay(100);Shot("20-long-medicine-row");w.SelectPage(0);
   w.Width=900;w.Height=650;await Task.Delay(100);Shot("18-compact-home");Verify("紧凑首页导航与新增仍可访问",w.Navigation.IsVisible&&w.AddButton.IsVisible&&w.BodyViewer.ScrollableHeight>0);w.Width=1200;w.Height=900;
   var expectedState=JsonSerializer.Serialize(w.Session.Engine.State,StateJson.Options);foreach(var theme in DesignTheme.Ids){w.ThemeChoice.SelectedIndex=Array.IndexOf(DesignTheme.Ids,theme);await Task.Delay(60);Verify("页面主题切换保留计划 "+theme,DesignTheme.Current==theme&&JsonSerializer.Serialize(w.Session.Engine.State,StateJson.Options)==expectedState);Shot("19-theme-"+theme);}w.ThemeChoice.SelectedIndex=0;
   var empty=new PageWindow(new PreviewSession(false)){Owner=w};empty.Show();await Task.Delay(150);Verify("首次首页空态不假装提醒运行",empty.PlanToggles.Count==0&&empty.PageTitle.Text=="暂无运行中的提醒");Shot("21-empty-home",empty);empty.SelectPage(1);await Task.Delay(80);Verify("药物列表空态可进入新增",empty.PlanToggles.Count==0&&empty.AddButton.IsEnabled);Shot("22-empty-medicine",empty);empty.SelectPage(0);var first=empty.OpenEditor(null,false);await Task.Delay(150);Verify("首次保存原子启用并刷新首页",first.TrySave()&&empty.Session.Engine.State.Running&&empty.Session.Engine.State.Plans.Count==1);await Task.Delay(80);Shot("23-first-save",empty);empty.Close();
  }catch(Exception ex){success=false;checks.Add(new{name="异常",passed=false,error=ex.ToString()});}
  finally{if(w.CurrentEditor is {} form)Close(form);NativeInput.Up();NativeInput.Move(cursor);File.WriteAllText(Path.Combine(directory,"page-test-results.json"),JsonSerializer.Serialize(new{success,startedAt=started,finishedAt=DateTimeOffset.Now,dpi=NativeInput.GetDpiForWindow(new WindowInteropHelper(w).Handle),checks,scope="Three baseline pages in memory, fixed demo clock, no scheduler timer or database. Not full product or all-device acceptance."},new JsonSerializerOptions{WriteIndented=true}));Application.Current.Shutdown(success?0:1);}
 }
}
